/**
 * Leader model catalog for Mastra router (`provider/model`).
 *
 * Built-in provider/model list is loaded from bundled config:
 *   packages/core/src/bundled/builtin-providers.json
 *
 * That file is generated by `npm run sync:model-registry` from
 * https://models.dev/api.json + builtin-providers.policy.json.
 * package:prepare runs the sync so release packages ship the latest registry.
 *
 * Runtime override (see resolveBuiltinProviders): when the user-side external
 * models.dev catalog (<root>/models-dev/api.json + meta.json) is fresher than
 * the bundled snapshot, it is curated on the fly and takes priority.
 *
 * @see https://models.dev
 * @see packages/core/src/bundled/builtin-providers.policy.json
 */

import { existsSync, readFileSync, statSync } from 'node:fs'
import { normalizeMastraProviderId } from './provider-ids.js'
import type { FeaturedPolicy } from './featured-policy.js'
import type { ThinkingIntensity } from './thinking-intensity.js'
// Static import so esbuild/package bundles the JSON (readFileSync of import.meta.url breaks in dist-runtime).
import builtinProvidersJson from './bundled/builtin-providers.json' with { type: 'json' }
import {
  buildBuiltinCatalog,
  loadBuiltinProvidersPolicy,
  type BuiltinProvidersCatalog,
  type BuiltinProvidersPolicy,
  type RegistryModelInfo,
} from './builtin-catalog.js'
import {
  loadModelsDevMeta,
  loadModelsDevRegistry,
  modelsDevCatalogPaths,
  type ModelsDevCatalogPaths,
  type ModelsDevMeta,
  type ModelsDevProviderRaw,
} from './models-dev-catalog.js'
import { toRawProvider } from './models-dev-registry-mapping.js'

export interface ModelOption {
  id: string
  label: string
  /** Short tag for UI chips */
  tag?: 'flagship' | 'fast' | 'coding' | 'cheap' | 'reasoning'
  /** Approximate context window (tokens) for UI hints */
  contextWindow?: number
  /** Supported thinking levels (models.dev reasoning_options when available). */
  thinkingIntensities?: ThinkingIntensity[]
  /** Supports tool calling (models.dev tool_call). */
  toolCall?: boolean
  /** Supports non-text input/output (models.dev modalities). */
  multimodal?: boolean
}

export interface ModelProviderDef {
  id: string
  name: string
  /** Env var Mastra / AI SDK typically reads */
  apiKeyEnv: string
  /** Optional alternate env names */
  apiKeyEnvAliases?: string[]
  docsUrl: string
  /** Default API style for OpenCode-like custom gateways */
  apiStyle?: 'openai' | 'anthropic' | 'google'
  /** Optional default base URL (OpenAI-compatible gateways) */
  baseURL?: string
  models: ModelOption[]
}

type BuiltinProvidersFile = {
  version: number
  generatedAt?: string
  defaultLeaderModel?: string
  recommended?: Array<{ id: string; label: string; reason: string }>
  providers?: ModelProviderDef[]
}

/** Minimal offline fallback if generated JSON is missing (should not happen in package). */
const FALLBACK_PROVIDERS: ModelProviderDef[] = [
  {
    id: 'openai',
    name: 'OpenAI',
    apiKeyEnv: 'OPENAI_API_KEY',
    docsUrl: 'https://platform.openai.com/docs/models',
    apiStyle: 'openai',
    models: [{ id: 'openai/gpt-4o', label: 'GPT-4o', tag: 'flagship', contextWindow: 128000 }],
  },
]

function loadBuiltinProvidersFile(): BuiltinProvidersFile {
  const raw = builtinProvidersJson as BuiltinProvidersFile
  if (!raw || !Array.isArray(raw.providers) || raw.providers.length === 0) {
    console.warn('[models-catalog] builtin-providers.json empty — using fallback')
    return {
      version: 0,
      defaultLeaderModel: 'openai/gpt-4o',
      recommended: [{ id: 'openai/gpt-4o', label: 'GPT-4o', reason: 'balanced' }],
      providers: FALLBACK_PROVIDERS,
    }
  }
  return raw
}

const builtinCatalog = loadBuiltinProvidersFile()

/**
 * Built-in providers only (from generated config). Prefer quality over coverage —
 * OpenRouter / Ollama / 硅基流动 etc. go through Custom gateway.
 */
export const MASTRA_PROVIDERS: ModelProviderDef[] =
  Array.isArray(builtinCatalog.providers) && builtinCatalog.providers.length > 0
    ? builtinCatalog.providers
    : FALLBACK_PROVIDERS

/** All secret env keys managed by settings (builtins + common aliases) */
export const SECRET_ENV_KEYS = [
  ...new Set([
    ...MASTRA_PROVIDERS.map((p) => p.apiKeyEnv),
    ...MASTRA_PROVIDERS.flatMap((p) => p.apiKeyEnvAliases ?? []),
  ]),
] as string[]

export const DEFAULT_LEADER_MODEL =
  typeof builtinCatalog.defaultLeaderModel === 'string' && builtinCatalog.defaultLeaderModel.trim()
    ? builtinCatalog.defaultLeaderModel.trim()
    : (MASTRA_PROVIDERS[0]?.models[0]?.id ?? 'openai/gpt-4o')

/** Quick-pick recommendations for empty state / chat bar */
export const RECOMMENDED_MODELS: { id: string; label: string; reason: string }[] =
  Array.isArray(builtinCatalog.recommended) && builtinCatalog.recommended.length > 0
    ? builtinCatalog.recommended
    : MASTRA_PROVIDERS.slice(0, 5).flatMap((p) =>
        p.models[0] ? [{ id: p.models[0].id, label: p.models[0].label, reason: 'flagship' }] : [],
      )

/** Product featured layer — intersect with RegistrySnapshot for default UI lists */
export const DEFAULT_FEATURED_POLICY: FeaturedPolicy = (() => {
  const recommendedOrder = new Map(RECOMMENDED_MODELS.map((m, i) => [m.id, i]))
  const entries: FeaturedPolicy['entries'] = []
  let fallbackSort = 0
  for (const p of MASTRA_PROVIDERS) {
    for (const m of p.models) {
      const recIdx = recommendedOrder.get(m.id)
      const hint = RECOMMENDED_MODELS.find((r) => r.id === m.id)?.reason
      entries.push({
        modelId: m.id,
        tag: m.tag,
        sort: recIdx !== undefined ? recIdx : 1000 + fallbackSort,
        ...(hint ? { hint } : {}),
      })
      fallbackSort += 1
    }
  }
  entries.sort((a, b) => a.sort - b.sort)
  return { version: 1, entries }
})()

export function findProviderForModel(modelId: string): ModelProviderDef | undefined {
  const prefix = modelId.split('/')[0]
  return (
    MASTRA_PROVIDERS.find((p) => p.models.some((m) => m.id === modelId)) ??
    MASTRA_PROVIDERS.find((p) => p.id === prefix)
  )
}

export function findProviderByEnvKey(envKey: string): ModelProviderDef | undefined {
  return MASTRA_PROVIDERS.find(
    (p) => p.apiKeyEnv === envKey || p.apiKeyEnvAliases?.includes(envKey),
  )
}

/**
 * Resolve env var names that can unlock a model id (builtin + custom gateway).
 */
export function resolveApiKeyEnvsForModel(
  modelId: string,
  custom?: { id: string; apiKeyEnv: string; name?: string; baseURL?: string }[] | null,
): { providerId: string; envKeys: string[] } | null {
  const id = modelId.trim()
  if (!id.includes('/')) return null
  const prefix = id.split('/')[0]!
  const canon = normalizeMastraProviderId(prefix)

  const builtin =
    findProviderForModel(id) ?? findProviderForModel(`${canon}/${id.split('/').slice(1).join('/')}`)
  if (builtin) {
    return {
      providerId: builtin.id,
      envKeys: [builtin.apiKeyEnv, ...(builtin.apiKeyEnvAliases ?? [])],
    }
  }
  const customHit = (custom ?? []).find(
    (c) => c.id === prefix || c.id === canon || normalizeMastraProviderId(c.id) === canon,
  )
  if (customHit) {
    const upper = customHit.id.replace(/[^a-zA-Z0-9]/g, '_').toUpperCase()
    const canonUpper = canon.replace(/[^a-zA-Z0-9]/g, '_').toUpperCase()
    const keys = [
      customHit.apiKeyEnv,
      `${upper}_API_KEY`,
      `CUSTOM_${upper}_API_KEY`,
      `${canonUpper}_API_KEY`,
      ...(canon === 'opencode-go' || canon === 'opencode' ? ['OPENCODE_API_KEY'] : []),
    ]
    return { providerId: canon, envKeys: [...new Set(keys)] }
  }
  const upper = prefix.replace(/[^a-zA-Z0-9]/g, '_').toUpperCase()
  const canonUpper = canon.replace(/[^a-zA-Z0-9]/g, '_').toUpperCase()
  return {
    providerId: canon,
    envKeys: [
      `${upper}_API_KEY`,
      `CUSTOM_${upper}_API_KEY`,
      `${canonUpper}_API_KEY`,
      `CUSTOM_${canonUpper}_API_KEY`,
      ...(canon === 'opencode-go' || canon === 'opencode' ? ['OPENCODE_API_KEY'] : []),
    ],
  }
}

/** True if any of the env keys is non-empty in process.env / secrets map */
export function hasAnyApiKey(
  envKeys: string[],
  env: NodeJS.ProcessEnv | Record<string, string | undefined> = process.env,
): boolean {
  return envKeys.some((k) => {
    const v = env[k]
    return typeof v === 'string' && v.trim().length > 0
  })
}

/**
 * Get the merged provider catalog from the sync mechanism.
 * Falls back to the static MASTRA_PROVIDERS if the sync module is unavailable.
 */
export async function getProviderCatalog(forceRefresh?: boolean): Promise<ModelProviderDef[]> {
  try {
    const { getLeaderModelCatalog } = await import('./models-catalog-sync.js')
    return getLeaderModelCatalog(forceRefresh)
  } catch {
    return MASTRA_PROVIDERS
  }
}

/**
 * Result of runtime resolution of the built-in provider list.
 * `providers` is always structurally compatible with {@link MASTRA_PROVIDERS}
 * (i.e. an array of {@link ModelProviderDef}).
 */
export type BuiltinProvidersResolution = {
  providers: ModelProviderDef[]
  /**
   * Where the result came from:
   * - `external`: runtime-curated from the user-side models.dev catalog (fresher than bundled)
   * - `bundled`: inline builtin-providers.json snapshot (build-time curated)
   * - `fallback`: hardcoded minimal list (bundled snapshot unavailable)
   */
  source: 'external' | 'bundled' | 'fallback'
  /** ISO timestamp of the data used to produce the list. */
  generatedAt: string
}

let resolveBuiltinCache: {
  key: string
  value: BuiltinProvidersResolution
} | null = null

function resolveBuiltinCacheKey(paths: ModelsDevCatalogPaths): string | null {
  try {
    if (!existsSync(paths.apiJsonPath)) return null
    const st = statSync(paths.apiJsonPath)
    const metaRaw = existsSync(paths.metaPath) ? readFileSync(paths.metaPath, 'utf8') : ''
    return `${st.size}:${st.mtimeMs}:${metaRaw}`
  } catch {
    return null
  }
}

function isStrictlyNewer(candidate: string | undefined, baseline: string): boolean {
  if (!candidate) return false
  const c = Date.parse(candidate)
  const b = Date.parse(baseline)
  if (Number.isNaN(c) || Number.isNaN(b)) return false
  return c > b
}

function mapProviderModels(providerId: string, p: ModelsDevProviderRaw): RegistryModelInfo[] {
  // Same mapping as sync-model-registry (models-dev-registry-mapping) so the
  // runtime curate output is identical to the build-time generated snapshot.
  return toRawProvider(providerId, p).models ?? []
}

function buildExternalCatalog(
  policy: BuiltinProvidersPolicy,
  registry: Record<string, ModelsDevProviderRaw>,
  meta: ModelsDevMeta,
  generatedAt: string,
): BuiltinProvidersCatalog {
  const registryByProvider: Record<string, RegistryModelInfo[]> = {}
  for (const pp of policy.providers) {
    const raw = registry[pp.id]
    if (!raw) continue
    registryByProvider[pp.id] = mapProviderModels(pp.id, raw)
  }
  // mastraPackageVersion doubles as the provenance stamp of the data source
  // (e.g. https://models.dev/api.json or npm:@opencode-ai/models@x.y.z/snapshot).
  return buildBuiltinCatalog(policy, registryByProvider, meta.sourceUrl ?? 'models.dev', generatedAt)
}

/**
 * Resolve the built-in provider list at runtime, preferring the freshest data:
 *
 * 1. External models.dev catalog (`<root>/models-dev/api.json`) when its
 *    meta.fetchedAt (or npm snapshot generatedAt) is newer than the bundled
 *    builtin-providers.json generatedAt → curate live with the bundled policy.
 * 2. Bundled inline snapshot (MASTRA_PROVIDERS default).
 * 3. Hardcoded fallback.
 *
 * Never throws (failures silently fall back so Settings/UI never crash).
 * Output shape is fully compatible with {@link MASTRA_PROVIDERS}.
 */
export function resolveBuiltinProviders(opts?: {
  paths?: ModelsDevCatalogPaths
  policy?: BuiltinProvidersPolicy
}): BuiltinProvidersResolution {
  const policy = opts?.policy ?? loadBuiltinProvidersPolicy()
  const paths = opts?.paths ?? modelsDevCatalogPaths()
  const bundledGeneratedAt =
    typeof builtinCatalog.generatedAt === 'string' ? builtinCatalog.generatedAt : ''
  const cacheKey = resolveBuiltinCacheKey(paths)

  if (cacheKey && resolveBuiltinCache?.key === cacheKey) return resolveBuiltinCache.value

  try {
    const meta = loadModelsDevMeta(paths)
    const registry = loadModelsDevRegistry(paths)
    if (registry && meta) {
      const externalFreshAt = meta.generatedAt ?? meta.fetchedAt
      if (isStrictlyNewer(externalFreshAt, bundledGeneratedAt)) {
        const catalog = buildExternalCatalog(policy, registry, meta, externalFreshAt)
        const value: BuiltinProvidersResolution = {
          providers: catalog.providers,
          source: 'external',
          generatedAt: externalFreshAt,
        }
        if (cacheKey) {
          resolveBuiltinCache = {
            key: cacheKey,
            value,
          }
        }
        return value
      }
    }
  } catch {
    // silent fallback — never let a resolver failure crash Settings/UI
  }

  const bundledProviders = builtinCatalog.providers
  const bundled = Array.isArray(bundledProviders) && bundledProviders.length > 0
  const value: BuiltinProvidersResolution = {
    providers: bundled ? bundledProviders : FALLBACK_PROVIDERS,
    source: bundled ? 'bundled' : 'fallback',
    generatedAt: bundledGeneratedAt,
  }
  if (cacheKey) {
    resolveBuiltinCache = {
      key: cacheKey,
      value,
    }
  }
  return value
}

/** Normalize api style for custom / OpenCode-like gateways */
export type ApiStyle = 'openai' | 'anthropic' | 'google'

export function normalizeApiStyle(raw: string | undefined | null): ApiStyle {
  const v = (raw ?? 'openai').toLowerCase().trim()
  if (v === 'anthropic' || v === 'claude') return 'anthropic'
  if (v === 'google' || v === 'gemini') return 'google'
  // Legacy `custom` was OpenAI-compatible baseURL routing — fold into openai.
  return 'openai'
}
